fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let mid: i32 = h / 2;
    let cols: i32 = 24;
    let cw: i32 = w / cols;
    let mut cur = [0; 24];
    let mut i: i32 = 0;
    while i < cols {
        cur[i] = host::display::state_get(8 + i);
        i = i + 1;
    }
    if host::display::pointer_down() == 1 {
        let mut tap: i32 = host::display::pointer_x() / cw;
        if tap < 0 { tap = 0; }
        if tap > cols - 1 { tap = cols - 1; }
        cur[tap] = 0 - 60;
    }
    i = 0;
    while i < cols {
        let left: i32 = if i == 0 { cur[0] } else { cur[i - 1] };
        let right: i32 = if i == cols - 1 { cur[cols - 1] } else { cur[i + 1] };
        let accel: i32 = (left + right) / 2 - cur[i];
        let mut v: i32 = host::display::state_get(32 + i) + accel / 2;
        v = v * 15 / 16;
        host::display::state_set(32 + i, v);
        host::display::state_set(8 + i, cur[i] + v);
        i = i + 1;
    }
    host::display::clear(0x000010);
    i = 0;
    while i < cols {
        let d: i32 = host::display::state_get(8 + i);
        if d < 0 {
            host::display::fill_rect(i * cw, mid + d, cw - 1, 0 - d, 0x2080ff);
        } else {
            host::display::fill_rect(i * cw, mid, cw - 1, d + 1, 0x2080ff);
        }
        i = i + 1;
    }
    host::display::present();
}
